const $=s=>document.querySelector(s);
const fmt=n=>'$'+Math.round(n).toLocaleString('es-CO');
const short=n=>n>=1e6?'$'+(n/1e6).toLocaleString('es-CO',{maximumFractionDigits:1})+' M':fmt(n);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"><use href="#i-${n}"/></svg>`;
const avatar=p=>`<div class="avatar">${esc(p.initials||p.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</div>`;
const dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString('es-CO',{day:'numeric',month:'short'});
