const patient=id=>patients.find(p=>p.id===Number(id));
const siteMatch=p=>state.site==='Todas las sedes'||p.site===state.site;
const scoped=items=>items.filter(x=>siteMatch(patient(x.patient)));
const period=items=>scoped(items).filter(x=>monthOf(x.date)===state.period);
const sum=(items,key='amount')=>items.reduce((a,x)=>a+Number(x[key]||0),0);
const patientPayments=id=>payments.filter(x=>x.patient===id);
const invoicePaid=id=>sum(payments.filter(x=>x.invoice===id));
const invoiceBalance=inv=>Math.max(0,inv.amount-invoicePaid(inv.id));
const patientBalance=id=>sum(invoices.filter(x=>x.patient===id).map(x=>({amount:invoiceBalance(x)})));
const nextAppointment=id=>appointments.filter(x=>x.patient===id&&x.date>='2026-09-28'&&!['Cancelada','Atendida'].includes(x.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];
const pendingQuotes=()=>scoped(quotes).filter(q=>['Enviada','En negociación'].includes(q.status));
const lateQuotes=()=>pendingQuotes().filter(q=>new Date('2026-09-28T12:00:00')-new Date(q.lastContact+'T12:00:00')>=7*86400000);
const noFuture=()=>patients.filter(p=>siteMatch(p)&&!nextAppointment(p.id)&&p.status!=='Nueva');
const needsConfirm=()=>scoped(appointments).filter(a=>a.date>='2026-09-28'&&['Por confirmar','Reservada'].includes(a.status));
const actions=()=>[{key:'quotes',count:lateQuotes().length,title:'Cotizaciones sin respuesta',detail:'Último contacto hace 7 días o más',view:'crm'}, {key:'confirm',count:needsConfirm().length,title:'Citas por confirmar',detail:'Próximas citas reservadas',view:'agenda'}, {key:'control',count:noFuture().length,title:'Pacientes sin cita futura',detail:'Evaluar seguimiento o control',view:'pacientes'}];
const metrics=()=>({invoiced:sum(period(invoices)),collected:sum(period(payments)),balance:sum(scoped(invoices).map(x=>({amount:invoiceBalance(x)}))),quotes:sum(pendingQuotes()),appointments:scoped(appointments).filter(a=>monthOf(a.date)===state.period&&!['Cancelada'].includes(a.status)).length,newPatients:patients.filter(p=>siteMatch(p)&&monthOf(p.created)===state.period).length});
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('show'),3100)}
function head(k,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`}
function btn(label,action,value,style=''){return `<button class="btn ${style}" data-${action}="${esc(value)}">${label}</button>`}
function ribbon(){return `<div class="demo-ribbon"><div class="statusline"><span></span> Datos ficticios conectados · Los cambios duran solo mientras esta página permanece abierta</div><div class="ribbon-actions"><button data-tour="start">Recorrido guiado</button><button data-reset="1">Reiniciar demo</button></div></div>`}
function periodControls(){return `<div class="range-controls"><select id="periodSelect" aria-label="Periodo"><option value="2026-09" ${state.period==='2026-09'?'selected':''}>Septiembre 2026</option><option value="2026-08" ${state.period==='2026-08'?'selected':''}>Agosto 2026</option></select></div>`}
function metric(label,value,sub,view,filter=''){return `<div class="surface metric" role="button" tabindex="0" data-metric="${view}:${filter}" aria-label="Explorar ${label}"><div class="m-top"><span>${label}</span>${icon(view==='agenda'?'calendar':view==='pacientes'?'users':view==='crm'?'brief':'chart')}</div><div class="value">${value}</div><div class="change neutral">${sub}</div></div>`}
function tour(){if(!state.tour)return '';let steps=[['1 · Origen','Valentina llegó por Instagram y quedó registrada como paciente.','detalle','Resumen'],['2 · Atención','Explora el registro clínico y las piezas relacionadas con su tratamiento.','detalle','Clínico'],['3 · Tratamiento','El plan conecta fases, profesional y presupuesto aprobado.','detalle','Tratamientos'],['4 · Finanzas','La factura y dos abonos dejan un saldo calculado desde movimientos.','detalle','Finanzas'],['5 · Seguimiento','Una acción queda ligada a su próxima cita y al historial comercial.','detalle','CRM']];return `<div class="tourbar"><div><b>${steps[state.tour-1][0]} · Caso Valentina Restrepo</b><p>${steps[state.tour-1][1]}</p></div><div class="toursteps">${steps.map((x,i)=>`<button class="${state.tour===i+1?'active':''}" data-tour="${i+1}">${i+1}</button>`).join('')}<button data-tour="stop">Cerrar</button></div></div>`}
function patientTable(rows,columns='full'){return `<div class="surface table-wrap"><table class="data-table"><thead><tr><th>Paciente</th><th>Origen</th><th>Tratamiento / interés</th><th>Próxima cita</th><th>Estado</th><th>Saldo</th></tr></thead><tbody>${rows.map(p=>{let t=treatments.find(x=>x.patient===p.id),q=quotes.find(x=>x.patient===p.id),a=nextAppointment(p.id);return `<tr class="clickable" data-patient="${p.id}"><td><div class="patient-cell">${avatar(p)}<strong>${esc(p.name)}</strong></div></td><td><strong>${esc(p.source)}</strong><br><small>${esc(p.campaign)}</small></td><td>${esc(t?.title||q?.title||'Valoración')}</td><td>${a?dateLabel(a.date)+' · '+a.time:'Sin cita'}</td><td><span class="pill ${p.status==='Por reactivar'?'wait':p.status==='Seguimiento'?'grey':''}">${esc(p.status)}</span></td><td>${fmt(patientBalance(p.id))}</td></tr>`}).join('')||`<tr><td colspan="6"><div class="empty">No hay registros para esta selección.</div></td></tr>`}</tbody></table></div>`}
function taskPanel(){return `<div class="surface"><div class="panel-head"><div><h2 class="section-title">¿Qué debe hacer hoy el equipo?</h2><div class="section-sub">Calculado desde los registros de la demo</div></div></div><div class="task-list">${actions().map(a=>`<div class="task"><div class="count">${a.count}</div><div><b>${a.title}</b><small>${a.detail}</small></div><button data-actionlist="${a.key}">Ver registros</button></div>`).join('')}</div></div>`}
function apptPanel(){let list=scoped(appointments).filter(a=>a.date===state.agendaDay).sort((a,b)=>a.time.localeCompare(b.time));return `<div class="surface"><div class="panel-head"><div><h2 class="section-title">Agenda · ${dateLabel(state.agendaDay)}</h2><div class="section-sub">${list.length} citas en las sedes seleccionadas</div></div><button class="link" data-nav="agenda">Abrir agenda</button></div><div class="appt-list">${list.map(a=>`<div class="appt"><span class="time">${a.time}</span>${avatar(patient(a.patient))}<div class="info"><b>${esc(patient(a.patient).name)}</b><small>${esc(a.type)}</small></div><span class="pill ${a.status==='Por confirmar'?'wait':a.status==='Reservada'?'grey':''}">${a.status}</span></div>`).join('')||'<div class="empty-compact">No hay citas este día.</div>'}</div></div>`}
function dashboard(){let m=metrics(),late=lateQuotes();return `${head('PANORAMA OPERATIVO','Buen día, equipo clínico','Indicadores del periodo y acciones ligadas a pacientes reales de esta simulación.',`${periodControls()}${btn('Nueva cita','modal','appointment','primary')}`)}${ribbon()}${tour()}<div class="grid cards4">${metric('Facturado',short(m.invoiced),'Facturas del periodo','finanzas','facturas')}${metric('Cobrado',short(m.collected),'Pagos del periodo','finanzas','pagos')}${metric('Citas del periodo',m.appointments,'Agenda del periodo','agenda')}${metric('Cotizaciones abiertas',short(m.quotes),pendingQuotes().length+' propuestas','crm','pendientes')}</div><div class="grid cols-main" style="margin-top:16px"><div class="grid"><div class="surface insight-hero"><div class="label">✦ OPORTUNIDAD BASADA EN DATOS</div><h2>${late.length} ${late.length===1?'cotización espera':'cotizaciones esperan'} seguimiento.</h2><p>${late.length?late.map(q=>patient(q.patient).name).join(' y ')+' tienen una propuesta sin respuesta reciente.':'No hay propuestas con 7 días o más sin contacto en esta selección.'}</p>${btn('Ver oportunidades','nav','crm','gold')}</div><div class="surface"><div class="panel-head"><div><h2 class="section-title">Ingresos cobrados</h2><div class="section-sub">Movimientos del escenario de demostración</div></div>${btn('Ver pagos','metric','finanzas:pagos')}</div><div class="chart-body">${bars(['2026-08','2026-09'].map(m=>({label:m==='2026-08'?'AGO':'SEP',value:sum(scoped(payments).filter(x=>monthOf(x.date)===m))})))}</div></div></div><div class="grid">${taskPanel()}${apptPanel()}</div></div>`}
function bars(items){let max=Math.max(...items.map(x=>x.value),1);return `<div class="chart-columns">${items.map(x=>`<div class="chart-col"><b>${short(x.value)}</b><div class="bar-visual" style="height:${Math.max(4,130*x.value/max)}px"></div><small>${esc(x.label)}</small></div>`).join('')}</div>`}
function patientsView(){let rows=patients.filter(p=>siteMatch(p)&&(state.filter==='Todos'||state.filter==='Sin cita'&&!nextAppointment(p.id)||p.status===state.filter)&&p.name.toLowerCase().includes(state.query.toLowerCase())&&(!state.campaignFilter||p.campaign===state.campaignFilter));return `${head('RELACIÓN CON EL PACIENTE','Pacientes','Una ficha reúne el recorrido completo de cada persona.',btn('Nuevo paciente','modal','patient','primary'))}${ribbon()}${tour()}${state.campaignFilter?`<div class="callout" style="margin-bottom:15px">Campaña: <b>${esc(state.campaignFilter)}</b> <button class="section-link" data-clear-campaign="1">Quitar filtro</button></div>`:''}<div class="filter-row">${['Todos','Activa','Nueva','Seguimiento','Por reactivar','Sin cita'].map(x=>`<button class="chip ${state.filter===x?'active':''}" data-filter="${x}">${x}<span class="chip-count">${patients.filter(p=>siteMatch(p)&&(x==='Todos'||x==='Sin cita'&&!nextAppointment(p.id)||p.status===x)).length}</span></button>`).join('')}</div>${patientTable(rows)}`}
function eventList(p){let list=[{date:p.created,type:'CRM',text:'Paciente creado · origen '+p.source,owner:'Sistema'},...appointments.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:'Agenda',text:x.type+' · '+x.status,owner:x.professional})),...quotes.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:'Cotización',text:(x.title||treatments.find(t=>t.id===x.treatment)?.title)+' · '+fmt(x.amount)+' · '+x.status,owner:x.owner})),...clinical.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:'Clínico',text:x.type+' · '+x.text,owner:x.professional})),...invoices.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:'Factura',text:x.number+' · '+fmt(x.amount),owner:'Finanzas'})),...payments.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:'Pago',text:fmt(x.amount)+' · '+x.method,owner:'Tesorería'})),...contacts.filter(x=>x.patient===p.id).map(x=>({date:x.date,type:x.type,text:x.text,owner:x.owner}))].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="timeline"><h3>Línea de tiempo · ${list.length} eventos</h3>${list.map(x=>`<div class="event"><span class="event-dot"></span><div><b>${esc(x.text)} <span class="event-tag">${esc(x.type)}</span></b><small>${dateLabel(x.date)} · ${esc(x.owner)}</small></div></div>`).join('')}</div>`}
function clinicalTab(p){if(state.role==='Comercial')return `<div class="lock">Acceso clínico restringido para este perfil.</div>`;let notes=clinical.filter(x=>x.patient===p.id),teeth=[18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28],flag=treatments.filter(x=>x.patient===p.id).flatMap(x=>x.tooth);return `<div class="panel-grid"><div><h3>Historia clínica</h3>${notes.length?notes.map(n=>`<div class="callout" style="margin-bottom:10px"><b>${esc(n.type)} · ${dateLabel(n.date)}</b><br>${esc(n.text)}<br><span class="note">${esc(n.professional)}</span></div>`).join(''):'<div class="empty-compact">Sin evoluciones en este escenario.</div>'}</div><div><h3>Odontograma exploratorio</h3><p class="note">Selecciona una pieza para ver su estado de muestra.</p><div class="tooth-grid">${teeth.map(n=>`<button class="tooth ${flag.includes(n)?'flag':''} ${state.tooth===n?'selected':''}" data-tooth="${n}" aria-label="Pieza ${n}">⌣<br>${n}</button>`).join('')}</div><div class="tooth-info"><b>Pieza ${state.tooth}</b> · ${flag.includes(state.tooth)?'Vinculada a un plan de tratamiento':'Sin hallazgos registrados'}</div></div></div>`}
function treatmentTab(p){let ts=treatments.filter(x=>x.patient===p.id);return `<h3>Planes de tratamiento</h3>${ts.map(t=>`<div class="callout" style="margin-bottom:12px"><div class="statusline"><strong>${esc(t.title)}</strong><span class="pill">${esc(t.status)}</span></div><p>${esc(t.specialty)} · ${esc(t.professional)} · desde ${dateLabel(t.start)}</p><b>Valor contratado: ${fmt(t.price)}</b><p class="note">${appointments.filter(a=>a.treatment===t.id).length} citas vinculadas · ${quotes.filter(q=>q.treatment===t.id).length} cotización vinculada</p></div>`).join('')||'<div class="empty-compact">Aún no hay tratamiento contratado. Revisa la oportunidad comercial.</div>'}<h3>Cotizaciones</h3>${quotes.filter(q=>q.patient===p.id).map(q=>`<div class="record"><div><b>${esc(q.title||treatments.find(t=>t.id===q.treatment)?.title)}</b><div class="meta">#C-${q.id} · ${dateLabel(q.date)} · ${q.status}</div></div><strong>${fmt(q.amount)}</strong></div>`).join('')||'<div class="empty-compact">Sin cotizaciones.</div>'}`}
function financeTab(p){let inv=invoices.filter(x=>x.patient===p.id),pay=patientPayments(p.id);return `<div class="detail-row"><div class="mini-stat"><small>Cotizado</small><b>${short(sum(quotes.filter(x=>x.patient===p.id)))}</b></div><div class="mini-stat"><small>Facturado</small><b>${short(sum(inv))}</b></div><div class="mini-stat"><small>Pagado · LTV neto</small><b>${short(sum(pay))}</b></div><div class="mini-stat"><small>Saldo</small><b>${short(patientBalance(p.id))}</b></div></div><div class="panel-grid" style="margin-top:18px"><div><h3>Facturas</h3>${inv.map(x=>`<div class="record"><div><b>${x.number}</b><div class="meta">${dateLabel(x.date)} · saldo ${fmt(invoiceBalance(x))}</div></div><strong>${fmt(x.amount)}</strong></div>`).join('')||'<div class="empty-compact">Sin facturas.</div>'}</div><div><h3>Pagos y abonos</h3>${pay.map(x=>`<div class="record"><div><b>${esc(x.method)}</b><div class="meta">${dateLabel(x.date)} · ${invoices.find(i=>i.id===x.invoice)?.number}</div></div><strong>${fmt(x.amount)}</strong></div>`).join('')||'<div class="empty-compact">Sin pagos.</div>'}</div></div>${inv.some(x=>invoiceBalance(x)>0)?`<div class="split-actions" style="margin-top:18px">${btn('Registrar abono de prueba','modal','payment','primary')}</div>`:''}`}
function crmTab(p){let qs=quotes.filter(x=>x.patient===p.id),cs=contacts.filter(x=>x.patient===p.id);return `<h3>Oportunidad y seguimiento</h3><div class="callout">${esc(p.nextAction)} · origen: ${esc(p.source)} / ${esc(p.campaign)}</div>${qs.map(q=>`<div class="record"><div><b>${esc(q.title||treatments.find(t=>t.id===q.treatment)?.title)} · ${esc(q.status)}</b><div class="meta">Responsable: ${esc(q.owner)} · último contacto ${dateLabel(q.lastContact)}</div></div><strong>${fmt(q.amount)}</strong></div>`).join('')}<h3>Interacciones</h3>${cs.map(c=>`<div class="record"><div><b>${esc(c.type)} · ${esc(c.text)}</b><div class="meta">${dateLabel(c.date)} · ${esc(c.owner)}</div></div></div>`).join('')||'<div class="empty-compact">Sin contactos registrados.</div>'}<div class="split-actions" style="margin-top:18px">${btn('Registrar contacto de prueba','modal','contact','primary')}${btn('Nueva cotización','modal','quote')}</div>`}
function patientDetail(){let p=patient(state.patient)||patients[0],a=nextAppointment(p.id),ts=treatments.filter(x=>x.patient===p.id);let content=state.tab==='Resumen'?`<div class="detail-row"><div class="mini-stat"><small>Ingresos netos históricos</small><b>${short(sum(patientPayments(p.id)))}</b></div><div class="mini-stat"><small>Saldo por cobrar</small><b>${short(patientBalance(p.id))}</b></div><div class="mini-stat"><small>Próxima cita</small><b style="font-size:14px">${a?dateLabel(a.date)+' · '+a.time:'Sin cita'}</b></div><div class="mini-stat"><small>Estado</small><b style="font-size:14px">${esc(p.status)}</b></div></div><div class="patient-story">${['Origen','Cita','Clínico','Tratamiento','Cotización','Pago','Seguimiento'].map((x,i)=>`<button data-story="${i}">${i+1}. ${x}</button>`).join('')}</div>${eventList(p)}`:state.tab==='Clínico'?clinicalTab(p):state.tab==='Tratamientos'?treatmentTab(p):state.tab==='Finanzas'?financeTab(p):state.tab==='Origen'?attributionPanel(p):state.tab==='Experiencia'?experiencePanel(p):crmTab(p);return `${head('PATIENT 360',esc(p.name),`${p.age} años · ${esc(p.site)} · origen: ${esc(p.source)}`,`${btn('Volver a pacientes','nav','pacientes')}${btn('Agendar cita','modal','appointment','primary')}`)}${ribbon()}${tour()}<div class="detail-layout"><div class="surface"><div class="patient-banner">${avatar(p)}<div><h2>${esc(p.name)}</h2><p>Paciente #P-${String(p.id).padStart(4,'0')} · ${esc(ts[0]?.title||quotes.find(x=>x.patient===p.id)?.title||'Valoración')}</p></div><span class="badge">${esc(p.status)}</span></div><div class="detail-tabs">${['Resumen','Experiencia','Origen','Clínico','Tratamientos','Finanzas','CRM'].map(x=>`<button class="${state.tab===x?'active':''}" data-tab="${x}">${x}</button>`).join('')}</div><div class="detail-content">${content}</div></div><div class="grid" style="align-content:start"><div class="surface side-card"><h3>Contacto y contexto</h3><div class="row"><span>Teléfono demo</span><b>${esc(p.phone)}</b></div><div class="row"><span>Correo demo</span><b>${esc(p.email)}</b></div><div class="row"><span>Campaña</span><b>${esc(p.campaign)}</b></div><div class="row"><span>Consentimiento de contacto</span><b>${p.consent?'Sí':'No'}</b></div>${btn('Registrar interacción','modal','contact')}</div><div class="surface side-card"><h3>Siguiente acción</h3><p>${esc(p.nextAction)}</p><p>${a?'Cita: '+fullDate(a.date)+' a las '+a.time:'No hay cita futura.'}</p>${btn('Gestionar agenda','nav','agenda','primary')}</div></div></div>`}
function agenda(){let list=scoped(appointments).filter(a=>a.date===state.agendaDay).sort((a,b)=>a.time.localeCompare(b.time));return `${head('OPERACIÓN CLÍNICA','Agenda','Reserva y confirma citas vinculadas a la ficha del paciente.',btn('Nueva cita','modal','appointment','primary'))}${ribbon()}<div class="filter-row">${['2026-09-28','2026-09-29','2026-09-30','2026-10-01','2026-10-02'].map(d=>`<button class="chip ${state.agendaDay===d?'active':''}" data-day="${d}">${dateLabel(d)} <span class="chip-count">${scoped(appointments).filter(a=>a.date===d).length}</span></button>`).join('')}</div><div class="surface table-wrap"><table class="data-table"><thead><tr><th>Hora</th><th>Paciente</th><th>Atención</th><th>Profesional</th><th>Sede</th><th>Estado / acción</th></tr></thead><tbody>${list.map(a=>`<tr><td><strong>${a.time}</strong></td><td><button class="section-link" data-patient="${a.patient}">${esc(patient(a.patient).name)}</button></td><td>${esc(a.type)}</td><td>${esc(a.professional)}</td><td>${esc(a.site)}</td><td><span class="pill ${a.status==='Por confirmar'?'wait':a.status==='Reservada'?'grey':''}">${a.status}</span> ${['Reservada','Por confirmar'].includes(a.status)?`<button class="section-link" data-confirm="${a.id}">Confirmar</button>`:''}</td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">No hay citas este día en esta sede.</div></td></tr>`}</tbody></table></div><div class="notice" style="margin-top:16px">Confirmar una cita modifica su estado en la agenda y añade un evento al historial Patient 360 durante esta sesión.</div>`}
function clinicalView(){if(state.role==='Comercial')return `${head('ATENCIÓN ODONTOLÓGICA','Espacio clínico','Acceso según perfil.')}${ribbon()}<div class="lock">Información clínica restringida para el perfil Comercial.</div>`;let list=scoped(clinical);return `${head('ATENCIÓN ODONTOLÓGICA','Espacio clínico','Evoluciones y tratamientos ligados al paciente y profesional.')}${ribbon()}<div class="grid cols-main"><div class="surface"><div class="panel-head"><h2 class="section-title">Evoluciones registradas</h2></div><div class="record-list">${list.map(n=>`<div class="record"><div><b>${esc(patient(n.patient).name)} · ${esc(n.type)}</b><div class="meta">${dateLabel(n.date)} · ${esc(n.professional)}</div><p class="note">${esc(n.text)}</p></div>${btn('Abrir ficha','patient',n.patient)}</div>`).join('')}</div></div><div class="surface side-card"><h3>Planes en curso</h3>${scoped(treatments).filter(t=>t.status==='En progreso').map(t=>`<div class="row"><span>${esc(patient(t.patient).name)}</span><button class="section-link" data-patient="${t.patient}" data-open-tab="Tratamientos">${esc(t.title)}</button></div>`).join('')}<p>Los registros del escenario se enlazan con tratamientos y citas.</p></div></div>`}
function crm(){let q=pendingQuotes(),stages=['Todas','Pendientes','Vencidas','Enviada','En negociación','Aprobada'];let rows=scoped(quotes).filter(x=>state.crmStage==='Todas'||state.crmStage==='Pendientes'&&['Enviada','En negociación'].includes(x.status)||state.crmStage==='Vencidas'&&lateQuotes().includes(x)||x.status===state.crmStage);return `${head('CRECIMIENTO Y RELACIÓN','CRM y seguimiento','Cotizaciones, contactos y acciones con trazabilidad.',btn('Nueva cotización','modal','quote','primary'))}${ribbon()}<div class="grid cards4" style="margin-bottom:16px">${metric('Cotizaciones abiertas',short(sum(q)),q.length+' oportunidades','crm','pendientes')}${metric('Sin contacto 7+ días',lateQuotes().length,'Requieren seguimiento','crm','vencidas')}${metric('Aprobadas',scoped(quotes).filter(x=>x.status==='Aprobada').length,'Del escenario','crm','aprobadas')}${metric('Pacientes sin cita',noFuture().length,'Revisar control','pacientes','Sin cita')}</div><div class="filter-row">${stages.map(x=>`<button class="chip ${state.crmStage===x?'active':''}" data-stage="${x}">${x}</button>`).join('')}</div><div class="surface table-wrap"><table class="data-table"><thead><tr><th>Paciente</th><th>Propuesta</th><th>Estado</th><th>Valor</th><th>Último contacto</th><th>Acción</th></tr></thead><tbody>${rows.map(x=>`<tr><td><button class="section-link" data-patient="${x.patient}" data-open-tab="CRM">${esc(patient(x.patient).name)}</button></td><td>${esc(x.title||treatments.find(t=>t.id===x.treatment)?.title)}</td><td><span class="pill ${x.status==='Enviada'?'wait':'grey'}">${x.status}</span></td><td>${fmt(x.amount)}</td><td>${dateLabel(x.lastContact)}</td><td>${['Enviada','En negociación'].includes(x.status)?btn('Aprobar y facturar','approve',x.id,'primary'):''} ${btn('Seguimiento','quickcontact',x.patient)}</td></tr>`).join('')}</tbody></table></div>`}
function approveQuote(id){let q=quotes.find(x=>x.id===Number(id));if(!q||!['Enviada','En negociación'].includes(q.status))return;let t={id:Math.max(...treatments.map(x=>x.id))+1,patient:q.patient,title:q.title||'Tratamiento',specialty:'Por asignar',status:'Programado',price:q.amount,professional:'Por asignar',start:'2026-09-28',tooth:[]};treatments.push(t);q.treatment=t.id;q.status='Aprobada';invoices.push({id:Math.max(...invoices.map(x=>x.id))+1,patient:q.patient,treatment:t.id,date:'2026-09-28',amount:q.amount,number:'FE-DEMO-'+(invoices.length+1)});patient(q.patient).status='Activa';patient(q.patient).nextAction='Agendar inicio del tratamiento';selectPatient(q.patient,'Finanzas');toast('Cotización aprobada, tratamiento y factura creados en la demo.')}
function finances(){let m=metrics();let inv=scoped(invoices).filter(x=>monthOf(x.date)===state.period),pay=scoped(payments).filter(x=>monthOf(x.date)===state.period);let rows=state.ledger==='pagos'?pay:state.ledger==='cartera'?scoped(invoices).filter(x=>invoiceBalance(x)>0):inv;return `${head('OPERACIÓN FINANCIERA','Finanzas','Cada saldo proviene de facturas menos pagos asociados.',periodControls())}${ribbon()}<div class="grid cards4">${metric('Cotizado abierto',short(m.quotes),pendingQuotes().length+' propuestas','crm','pendientes')}${metric('Facturado',short(m.invoiced),'Periodo seleccionado','finanzas','facturas')}${metric('Cobrado',short(m.collected),'Periodo seleccionado','finanzas','pagos')}${metric('Cartera',short(m.balance),'Saldo acumulado','finanzas','cartera')}</div><div class="filter-row" style="margin-top:18px">${[['facturas','Facturas'],['pagos','Pagos'],['cartera','Cartera']].map(x=>`<button class="chip ${state.ledger===x[0]?'active':''}" data-ledger="${x[0]}">${x[1]}</button>`).join('')}</div><div class="surface table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Paciente</th><th>Documento</th><th>${state.ledger==='cartera'?'Saldo':'Valor'}</th><th>Detalle</th></tr></thead><tbody>${rows.map(x=>`<tr class="clickable" data-patient="${x.patient}" data-open-tab="Finanzas"><td>${dateLabel(x.date)}</td><td><strong>${esc(patient(x.patient).name)}</strong></td><td>${x.number||invoices.find(i=>i.id===x.invoice)?.number||''}</td><td>${fmt(state.ledger==='cartera'?invoiceBalance(x):x.amount)}</td><td>${state.ledger==='pagos'?esc(x.method):'Facturado '+fmt(x.amount)+' · pagado '+fmt(invoicePaid(x.id))}</td></tr>`).join('')||`<tr><td colspan="5"><div class="empty">Sin movimientos en el periodo.</div></td></tr>`}</tbody></table></div>`}
function marketing(){let rows=campaigns.map(c=>{let ps=patients.filter(p=>siteMatch(p)&&p.campaign===c.name),ids=ps.map(p=>p.id);return {...c,leads:ps.length,quotes:quotes.filter(q=>ids.includes(q.patient)),collected:sum(payments.filter(x=>ids.includes(x.patient)))}});return `${head('ADQUISICIÓN Y FIDELIZACIÓN','Marketing','Del origen del paciente al ingreso cobrado, con consentimiento visible.')}${ribbon()}<div class="grid cards4">${metric('Pacientes nuevos',metrics().newPatients,'En el periodo','pacientes','Nueva')}${metric('Campañas',campaigns.filter(x=>x.spend>0).length,'Escenario de muestra','marketing')}${metric('Con consentimiento',patients.filter(p=>siteMatch(p)&&p.consent).length,'Contactos aptos','marketing')}${metric('Sin consentimiento',patients.filter(p=>siteMatch(p)&&!p.consent).length,'Excluir de campañas','marketing')}</div><div class="surface table-wrap" style="margin-top:16px"><table class="data-table"><thead><tr><th>Campaña</th><th>Canal</th><th>Gasto demo</th><th>Pacientes</th><th>Cotizado</th><th>Cobrado histórico</th></tr></thead><tbody>${rows.map(c=>`<tr class="clickable" data-campaign="${esc(c.name)}"><td><strong>${esc(c.name)}</strong></td><td>${esc(c.channel)}</td><td>${fmt(c.spend)}</td><td>${c.leads}</td><td>${fmt(sum(c.quotes))}</td><td>${fmt(c.collected)}</td></tr>`).join('')}</tbody></table><div class="table-note">Haz clic en una campaña para ver los pacientes que la integran. No se envían comunicaciones.</div></div>`}
function analytics(){let m=metrics(),ps=patients.filter(siteMatch),src=[...new Set(ps.map(x=>x.source))].map(x=>({label:x,value:ps.filter(p=>p.source===x).length}));let bySite=['El Tesoro','Laureles'].filter(s=>state.site==='Todas las sedes'||s===state.site).map(s=>({label:s,value:sum(invoices.filter(x=>patient(x.patient).site===s&&monthOf(x.date)===state.period))}));return `${head('BUSINESS INTELLIGENCE','Analítica','Definiciones transparentes y detalle hasta cada registro.',periodControls())}${ribbon()}<div class="grid cards4">${metric('Pacientes registrados',ps.length,'En la sede seleccionada','pacientes')}${metric('Nuevos',m.newPatients,'Alta en el periodo','pacientes','Nueva')}${metric('Citas del periodo',m.appointments,'Excluye canceladas','agenda')}${metric('Cobrado',short(m.collected),'Pagos válidos del periodo','finanzas','pagos')}</div><div class="finance-split" style="margin-top:16px"><div class="surface panel-pad"><h2 class="section-title">Facturación por sede</h2>${bars(bySite)}</div><div class="surface panel-pad"><h2 class="section-title">Pacientes por origen</h2>${bars(src)}</div></div><div class="surface side-card" style="margin-top:16px"><h3>Diccionario de indicadores</h3><div class="row"><span>LTV del paciente</span><b>Suma de sus pagos válidos</b></div><div class="row"><span>Cartera</span><b>Facturas menos abonos aplicados</b></div><div class="row"><span>Cotizaciones abiertas</span><b>Enviadas + en negociación</b></div><div class="row"><span>Nuevo paciente</span><b>Fecha de creación en el periodo</b></div><div class="row"><span>Citas</span><b>Fecha dentro del periodo, sin canceladas</b></div></div>`}
function intelligence(){let a=actions();return `${head('DATOS → CONTEXTO → ACCIÓN','Centro de inteligencia','Cada alerta abre los registros que la originan.')}${ribbon()}<div class="grid cols-main"><div class="surface"><div class="panel-head"><div><h2 class="section-title">Señales del escenario</h2><div class="section-sub">Reglas explícitas sobre datos de demostración</div></div></div>${a.map(x=>`<div class="insight-card"><div class="count">${x.count}</div><div><b>${x.title}</b><p>${x.detail}</p></div>${btn('Ver origen','actionlist',x.key)}</div>`).join('')}</div>${taskPanel()}</div>`}
function inventoryView(){let rows=inventory.filter(x=>state.site==='Todas las sedes'||x.site===state.site);return `${head('RECURSOS CLÍNICOS','Inventario','Existencias de ejemplo por sede y alertas de mínimo.')}${ribbon()}<div class="grid metrics2" style="margin-bottom:16px">${metric('Referencias mostradas',rows.length,'Insumos de la demo','inventario')}${metric('Bajo mínimo',rows.filter(x=>x.stock<x.min).length,'Requieren reposición','inventario')}</div><div class="surface table-wrap"><table class="data-table"><thead><tr><th>Insumo</th><th>Sede</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.name)}</strong></td><td>${x.site}</td><td>${x.stock} ${x.unit}</td><td>${x.min}</td><td><span class="pill ${x.stock<x.min?'wait':''}">${x.stock<x.min?'Reponer':'Disponible'}</span></td></tr>`).join('')}</tbody></table></div>`}
const views={inicio:dashboard,pacientes:patientsView,detalle:patientDetail,agenda,clinico:clinicalView,crm,finanzas:finances,marketing,analitica:analytics,inteligencia:intelligence,inventario:inventoryView};
function render(){let entries=[['ESPACIO DE TRABAJO',nav.slice(0,6)],['GESTIÓN Y ANÁLISIS',nav.slice(6)]];$('#nav').innerHTML=entries.map(([title,items])=>`<div class="nav-section">${title}</div>${items.map(([key,label,i])=>`<button class="nav-btn ${state.view===key?'active':''}" data-nav="${key}">${icon(i)}<span>${label}</span></button>`).join('')}`).join('');$('#crumbTitle').textContent=nav.find(x=>x[0]===state.view)?.[1]||'Patient 360';$('#content').innerHTML=(views[state.view]||dashboard)();$('#sidebar').classList.remove('open');$('#siteSelect').value=state.site;$('#roleSelect').value=state.role;$('#globalSearch').value=state.query}
function go(view,filter){state.view=view;if(view==='pacientes'&&!filter)state.campaignFilter='';if(view==='finanzas')state.ledger=filter||'facturas';if(view==='crm')state.crmStage=filter==='aprobadas'?'Aprobada':filter==='pendientes'?'Pendientes':filter==='vencidas'?'Vencidas':'Todas';if(view==='pacientes'&&filter)state.filter=filter;render();window.scrollTo(0,0)}
function selectPatient(id,tab='Resumen'){state.patient=Number(id);state.tab=tab;go('detalle')}
function modal(type,patientId=state.patient){let p=patient(patientId),title={patient:'Nuevo paciente',appointment:'Nueva cita',quote:'Nueva cotización',payment:'Registrar abono',contact:'Registrar contacto'}[type];state.modal={type,patientId};let patientField=type==='patient'?`<label class="full">Nombre completo<input name="name" required maxlength="80" placeholder="Ej. Ana López"></label><label>Sede<select name="site"><option>El Tesoro</option><option>Laureles</option></select></label><label>Origen<select name="source"><option>Referido</option><option>Instagram</option><option>Google</option></select></label>`:`<label class="full">Paciente<select name="patient" required>${patients.map(x=>`<option value="${x.id}" ${x.id===patientId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>`;
let fields={patient:`<label>Edad<input type="number" name="age" min="1" max="110" required placeholder="30"></label><label>Teléfono demo<input name="phone" required placeholder="300 000 0199" maxlength="20"></label><label>Correo demo<input type="email" name="email" placeholder="ana.demo@example.com"></label>`,appointment:`<label>Fecha<input type="date" name="date" value="2026-09-30" min="2026-09-28" required></label><label>Hora<input type="time" name="time" value="10:00" required></label><label class="full">Tipo de cita<input name="title" required placeholder="Valoración / control"></label>`,quote:`<label>Tratamiento propuesto<input name="title" required placeholder="Ej. Implantología"></label><label>Valor COP<input type="number" name="amount" min="1" step="1000" required placeholder="3500000"></label>`,payment:`<label>Factura<select name="invoice" required>${invoices.filter(x=>invoiceBalance(x)>0).map(x=>`<option value="${x.id}" ${x.patient===patientId?'selected':''}>${x.number} · ${esc(patient(x.patient).name)} · saldo ${fmt(invoiceBalance(x))}</option>`).join('')}</select></label><label>Abono COP<input type="number" name="amount" min="1" step="1000" required placeholder="500000"></label>`,contact:`<label>Canal<select name="channel"><option>Llamada</option><option>WhatsApp</option><option>Email</option></select></label><label class="full">Resultado<input name="result" required placeholder="Ej. Se confirmó la próxima cita"></label>`}[type];$('#modalRoot').innerHTML=`<div class="modal-back" id="modalBack"><form class="modal" id="demoForm"><h2>${title}</h2><p>Operación de prueba. El cambio se reflejará en las vistas relacionadas durante esta sesión.</p><div class="form-grid">${patientField}${fields}</div><div class="modal-actions"><button type="button" class="btn" data-close="1">Cancelar</button><button class="btn primary" type="submit">Guardar en demo</button></div></form></div>`;$('#demoForm input')?.focus()}
function closeModal(){$('#modalRoot').innerHTML='';state.modal=null}
function saveForm(e){e.preventDefault();let d=Object.fromEntries(new FormData(e.target).entries()),t=state.modal.type,id=Number(d.patient),name='';if(t==='patient'){let newId=Math.max(...patients.map(x=>x.id))+1;patients.push({id:newId,name:d.name.trim(),age:Number(d.age),site:d.site,source:d.source,campaign:d.source==='Referido'?'Referidos':d.source==='Google'?'Ortodoncia Medellín':'Sonrisa consciente',phone:d.phone,email:d.email||'Sin correo',status:'Nueva',consent:false,created:'2026-09-28',last:'2026-09-28',nextAction:'Completar datos y agendar valoración'});name='Paciente creado';selectPatient(newId)}else if(t==='appointment'){let p=patient(id),same=appointments.some(a=>a.date===d.date&&a.time===d.time&&a.site===p.site&&a.status!=='Cancelada');if(same){toast('Ese horario ya está ocupado en la sede. Elige otro.');return}let newId=Math.max(...appointments.map(x=>x.id))+1;appointments.push({id:newId,patient:id,date:d.date,time:d.time,type:d.title.trim(),professional:'Por asignar',site:p.site,status:'Reservada',treatment:null});state.agendaDay=d.date;name='Cita reservada';go('agenda')}else if(t==='quote'){quotes.push({id:Math.max(...quotes.map(x=>x.id))+1,patient:id,treatment:null,title:d.title.trim(),amount:Number(d.amount),status:'Enviada',date:'2026-09-28',lastContact:'2026-09-28',owner:'Equipo comercial'});patient(id).status='Seguimiento';name='Cotización creada';selectPatient(id,'CRM')}else if(t==='payment'){let invoice=invoices.find(x=>x.id===Number(d.invoice));let amount=Number(d.amount);if(!invoice||amount>invoiceBalance(invoice)){toast('El abono debe ser menor o igual al saldo de la factura.');return}payments.push({id:Math.max(...payments.map(x=>x.id))+1,patient:invoice.patient,invoice:invoice.id,date:'2026-09-28',amount,method:'Pago de prueba'});id=invoice.patient;name='Abono aplicado';selectPatient(id,'Finanzas')}else if(t==='contact'){contacts.push({id:Math.max(...contacts.map(x=>x.id))+1,patient:id,date:'2026-09-28',type:d.channel,text:d.result.trim(),owner:'Equipo demo'});quotes.filter(x=>x.patient===id&&['Enviada','En negociación'].includes(x.status)).forEach(x=>x.lastContact='2026-09-28');name='Contacto registrado';selectPatient(id,'CRM')}closeModal();toast(name+' · Las vistas relacionadas se actualizaron.')}
function reset(){window.location.reload()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-nav],[data-patient],[data-tab],[data-filter],[data-tooth],[data-modal],[data-close],[data-metric],[data-day],[data-confirm],[data-actionlist],[data-stage],[data-ledger],[data-tour],[data-story],[data-quickcontact],[data-campaign],[data-reset],[data-approve],[data-clear-campaign]');if(!b){if(e.target.id==='modalBack')closeModal();return}let d=b.dataset;if(d.nav)go(d.nav);else if(d.patient)selectPatient(d.patient,d.openTab||'Resumen');else if(d.tab){state.tab=d.tab;render()}else if(d.filter){state.filter=d.filter;render()}else if(d.tooth){state.tooth=Number(d.tooth);render()}else if(d.modal)modal(d.modal);else if(d.close)closeModal();else if(d.metric){let [view,filter]=d.metric.split(':');go(view,filter)}else if(d.day){state.agendaDay=d.day;render()}else if(d.confirm){let a=appointments.find(x=>x.id===Number(d.confirm));a.status='Confirmada';render();toast('Cita confirmada y reflejada en Patient 360.')}else if(d.actionlist){if(d.actionlist==='quotes')go('crm','vencidas');if(d.actionlist==='confirm')go('agenda');if(d.actionlist==='control')go('pacientes','Sin cita')}else if(d.stage){state.crmStage=d.stage;render()}else if(d.ledger){state.ledger=d.ledger;render()}else if(d.tour){if(d.tour==='stop')state.tour=0;else state.tour=d.tour==='start'?1:Number(d.tour);if(state.tour){state.patient=1;state.tab=['Resumen','Resumen','Clínico','Tratamientos','Finanzas','CRM'][state.tour];state.view='detalle'}render();window.scrollTo(0,0)}else if(d.story){state.tab=['Resumen','Resumen','Clínico','Tratamientos','Tratamientos','Finanzas','CRM'][Number(d.story)];render()}else if(d.quickcontact)modal('contact',Number(d.quickcontact));else if(d.campaign){state.view='pacientes';state.filter='Todos';state.campaignFilter=d.campaign;state.query='';render()}else if(d.clearCampaign){state.campaignFilter='';render()}else if(d.approve)approveQuote(d.approve);else if(d.reset)reset()});
document.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.classList.contains('metric')){e.preventDefault();e.target.click()}if(e.key==='Escape')closeModal()});document.addEventListener('submit',e=>{if(e.target.id==='demoForm')saveForm(e)});$('#globalSearch').addEventListener('input',e=>{state.query=e.target.value;state.campaignFilter='';state.view='pacientes';render()});$('#siteSelect').addEventListener('change',e=>{state.site=e.target.value;render()});$('#roleSelect').addEventListener('change',e=>{state.role=e.target.value;render()});$('#notifyBtn').addEventListener('click',()=>go('inteligencia'));$('#menuBtn').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));document.addEventListener('change',e=>{if(e.target.id==='periodSelect'){state.period=e.target.value;render()}});render();
if(document.modelContext?.registerTool){for(const tool of [{name:'search_demo_patients',title:'Buscar pacientes demo',description:'Filtra pacientes ficticios por nombre y abre el listado.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:false},execute({query}){if(typeof query!=='string')throw Error('Consulta inválida');state.query=query;go('pacientes');return {count:patients.filter(p=>p.name.toLowerCase().includes(query.toLowerCase())).length}}},{name:'open_demo_patient',title:'Abrir Patient 360 demo',description:'Abre la ficha de un paciente ficticio por ID.',inputSchema:{type:'object',properties:{patientId:{type:'integer'}},required:['patientId'],additionalProperties:false},annotations:{readOnlyHint:false},execute({patientId}){if(!patient(patientId))throw Error('Paciente no encontrado');selectPatient(patientId);return {patient:patient(patientId).name}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
